import React, { useState, useRef, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { X, User, ShieldCheck, ArrowRight, AlertCircle, Phone } from 'lucide-react';
import Logo from './Logo';
import styles from './LoginModal.module.css';

// Firebase Phone Auth with Test Number support (no billing needed)
let firebasePhoneAuth = null;
function getFirebasePhoneAuth() {
  if (firebasePhoneAuth) return firebasePhoneAuth;
  try {
    const { auth } = require('../firebase');
    const { signInWithPhoneNumber, RecaptchaVerifier } = require('firebase/auth');
    firebasePhoneAuth = { auth, signInWithPhoneNumber, RecaptchaVerifier };
    return firebasePhoneAuth;
  } catch (e) {
    console.warn('Firebase not available:', e.message);
    return null;
  }
}

export default function LoginModal() {
  const { loginModalOpen, closeLoginModal, loginWithPhone } = useAuth();

  const [step, setStep] = useState(1); // 1: Name & Phone, 2: OTP
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [devOtp, setDevOtp] = useState('');
  const [resendTimer, setResendTimer] = useState(30);
  const [confirmationResult, setConfirmationResult] = useState(null);
  const [useFirebase, setUseFirebase] = useState(false);

  const otpInputsRef = useRef([]);
  const recaptchaContainerRef = useRef(null);
  const recaptchaVerifierRef = useRef(null);

  // Reset state whenever modal opens
  useEffect(() => {
    if (loginModalOpen) {
      setStep(1);
      setError('');
      setLoading(false);
      setOtp(['', '', '', '', '', '']);
      setDevOtp('');
      setResendTimer(30);
      setConfirmationResult(null);
      setUseFirebase(false);
    }
  }, [loginModalOpen]);

  // Resend countdown timer
  useEffect(() => {
    if (step === 2 && resendTimer > 0) {
      const timer = setInterval(() => setResendTimer((t) => t - 1), 1000);
      return () => clearInterval(timer);
    }
  }, [step, resendTimer]);

  // Focus first OTP input when step 2 opens
  useEffect(() => {
    if (step === 2) {
      setTimeout(() => otpInputsRef.current[0]?.focus(), 100);
    }
  }, [step]);

  if (!loginModalOpen) return null;

  const cleanPhone = phone.replace(/[^0-9]/g, '').slice(-10);

  // Set up invisible reCAPTCHA (required by Firebase even for test numbers)
  function setupRecaptcha() {
    const fb = getFirebasePhoneAuth();
    if (!fb) return null;
    try {
      if (recaptchaVerifierRef.current) {
        try { recaptchaVerifierRef.current.clear(); } catch(e) {}
        recaptchaVerifierRef.current = null;
      }
      const verifier = new fb.RecaptchaVerifier(fb.auth, 'recaptcha-container', {
        size: 'invisible',
        callback: () => {},
      });
      recaptchaVerifierRef.current = verifier;
      return verifier;
    } catch (e) {
      console.warn('reCAPTCHA setup error:', e.message);
      return null;
    }
  }

  // Handle Step 1: Send OTP
  const handleSendOtp = async (e) => {
    e?.preventDefault();
    setError('');

    if (!name.trim()) { setError('Please enter your full name'); return; }
    if (cleanPhone.length !== 10) { setError('Please enter a valid 10-digit mobile number'); return; }

    setLoading(true);
    try {
      // Try Firebase phone auth first (supports test numbers on free plan)
      const fb = getFirebasePhoneAuth();
      if (fb) {
        try {
          const verifier = setupRecaptcha();
          if (verifier) {
            const phoneWithCountry = `+91${cleanPhone}`;
            const result = await fb.signInWithPhoneNumber(fb.auth, phoneWithCountry, verifier);
            setConfirmationResult(result);
            setUseFirebase(true);
            setStep(2);
            setResendTimer(30);
            console.log('✅ Firebase OTP sent to', phoneWithCountry);
            return;
          }
        } catch (fbErr) {
          console.warn('Firebase phone auth failed, falling back to dev OTP:', fbErr.message);
          // If Firebase fails, fall through to backend dev OTP
        }
      }

      // Fallback: Backend dev OTP (file-based, persists across restarts)
      const { sendPhoneOtp } = require('../services/api');
      const res = await sendPhoneOtp({ phone: cleanPhone });
      if (res.data?.devOtp) setDevOtp(res.data.devOtp);
      setUseFirebase(false);
      setStep(2);
      setResendTimer(30);
    } catch (err) {
      setError(err.response?.data?.message || err.message || 'Failed to send OTP. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Handle Step 2: Verify OTP
  const handleVerifyOtp = async (e) => {
    e?.preventDefault();
    const enteredOtp = otp.join('').trim();
    if (enteredOtp.length !== 6) { setError('Please enter the complete 6-digit OTP'); return; }

    setError('');
    setLoading(true);
    try {
      if (useFirebase && confirmationResult) {
        // Firebase verification — works with test numbers from Firebase Console
        const userCredential = await confirmationResult.confirm(enteredOtp);
        const firebaseToken = await userCredential.user.getIdToken();
        // Send Firebase token to backend to issue our JWT
        const api = require('../services/api').default;
        const res = await api.post('/auth/firebase-phone-login', {
          firebaseToken,
          name: name.trim(),
          phone: cleanPhone,
        });
        if (res.data?.success) {
          localStorage.setItem('pb_token', res.data.token);
          window.location.reload();
          closeLoginModal();
          return;
        }
      } else {
        // Backend dev OTP flow
        await loginWithPhone(name.trim(), cleanPhone, enteredOtp);
        closeLoginModal();
      }
    } catch (err) {
      const msg = err?.response?.data?.message || err?.message || '';
      if (msg.includes('invalid-verification-code') || msg.includes('Invalid OTP')) {
        setError('Wrong OTP code. Please check and try again.');
      } else if (msg.includes('expired')) {
        setError('OTP expired. Please resend.');
      } else {
        setError(msg || 'Verification failed. Please try again.');
      }
    } finally {
      setLoading(false);
    }
  };

  // Handle individual OTP box typing
  const handleOtpChange = (index, val) => {
    const char = val.slice(-1);
    if (char && !/[0-9]/.test(char)) return;
    const newOtp = [...otp];
    newOtp[index] = char;
    setOtp(newOtp);
    if (char && index < 5) otpInputsRef.current[index + 1]?.focus();
    if (char && index === 5 && newOtp.every((d) => d !== '')) {
      const fullOtp = newOtp.join('');
      setLoading(true);
      const verifyFn = useFirebase && confirmationResult
        ? async () => {
            const uc = await confirmationResult.confirm(fullOtp);
            const ft = await uc.user.getIdToken();
            const api = require('../services/api').default;
            const r = await api.post('/auth/firebase-phone-login', { firebaseToken: ft, name: name.trim(), phone: cleanPhone });
            if (r.data?.success) { localStorage.setItem('pb_token', r.data.token); window.location.reload(); closeLoginModal(); }
          }
        : () => loginWithPhone(name.trim(), cleanPhone, fullOtp).then(() => closeLoginModal());
      verifyFn().catch((err) => {
        setError(err?.response?.data?.message || err?.message || 'Invalid OTP. Please try again.');
        setLoading(false);
      });
    }
  };

  const handleOtpKeyDown = (index, e) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) otpInputsRef.current[index - 1]?.focus();
  };

  const handleOtpPaste = (e) => {
    e.preventDefault();
    const pastedData = e.clipboardData.getData('text').replace(/[^0-9]/g, '').slice(0, 6);
    if (!pastedData) return;
    const newOtp = [...otp];
    for (let i = 0; i < pastedData.length; i++) newOtp[i] = pastedData[i];
    setOtp(newOtp);
    if (pastedData.length === 6) {
      setLoading(true);
      loginWithPhone(name.trim(), cleanPhone, pastedData)
        .then(() => closeLoginModal())
        .catch((err) => { setError(err?.response?.data?.message || 'Invalid OTP.'); setLoading(false); });
    } else {
      otpInputsRef.current[pastedData.length]?.focus();
    }
  };

  return (
    <div className={styles.overlay} onClick={(e) => e.target === e.currentTarget && closeLoginModal()}>
      {/* Invisible reCAPTCHA container */}
      <div id="recaptcha-container" ref={recaptchaContainerRef} style={{ position: 'absolute', bottom: 0, opacity: 0, pointerEvents: 'none' }} />

      <div className={styles.modal}>
        <button className={styles.closeBtn} onClick={closeLoginModal}><X size={20} /></button>

        <div className={styles.header}>
          <div className={styles.brandWrap}>
            <Logo size="md" theme="forest" showTagline={true} />
          </div>
          <h2 className={styles.title}>
            {step === 1 ? 'Sign in to ProBridge' : 'Verify your number'}
          </h2>
        </div>

        {/* Step indicator */}
        <div className={styles.stepIndicator}>
          <div className={`${styles.stepDot} ${step >= 1 ? styles.stepActive : ''}`}>1</div>
          <div className={styles.stepLine} />
          <div className={`${styles.stepDot} ${step >= 2 ? styles.stepActive : ''}`}>2</div>
        </div>

        {/* Phone display on step 2 */}
        {step === 2 && (
          <p className={styles.otpSubtitle}>
            OTP sent to <strong>+91 {cleanPhone}</strong>
            {useFirebase && <span className={styles.firebaseBadge}> via Firebase</span>}
            &nbsp;
            <button className={styles.editPhoneBtn} onClick={() => { setStep(1); setError(''); }}>Edit</button>
          </p>
        )}

        {/* Error Banner */}
        {error && (
          <div className={styles.errorBanner}>
            <AlertCircle size={16} />
            <span>{error}</span>
          </div>
        )}

        {/* Dev OTP Hint */}
        {devOtp && step === 2 && !useFirebase && (
          <div className={styles.devOtpHint}>
            <span>Dev Code:</span>
            <span
              className={styles.devOtpBadge}
              style={{ cursor: 'pointer' }}
              onClick={() => setOtp(devOtp.split('').slice(0, 6))}
              title="Click to auto-fill OTP"
            >
              {devOtp} (Click to fill)
            </span>
          </div>
        )}

        {/* Step 1: Name & Mobile Number */}
        {step === 1 ? (
          <form onSubmit={handleSendOtp} className={styles.form}>
            <div className={styles.field}>
              <label className={styles.label}>Full Name</label>
              <div className={styles.inputWrap}>
                <User size={18} className={styles.fieldIcon} />
                <input
                  type="text"
                  className={styles.input}
                  placeholder="Enter your full name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  autoFocus
                  required
                />
              </div>
            </div>

            <div className={styles.field}>
              <label className={styles.label}>Mobile Number</label>
              <div className={styles.phoneInputWrap}>
                <div className={styles.countryCode}>
                  <span>🇮🇳</span>
                  <span>+91</span>
                </div>
                <input
                  type="tel"
                  className={styles.phoneInput}
                  placeholder="10-digit mobile number"
                  maxLength={10}
                  value={phone}
                  onChange={(e) => setPhone(e.target.value.replace(/[^0-9]/g, ''))}
                  required
                />
              </div>
            </div>

            <button
              type="submit"
              className={styles.submitBtn}
              disabled={loading || !name.trim() || cleanPhone.length !== 10}
            >
              {loading ? 'Sending OTP…' : <><span>Continue</span><ArrowRight size={17} /></>}
            </button>
          </form>
        ) : (
          /* Step 2: OTP Verification */
          <form onSubmit={handleVerifyOtp} className={styles.form}>
            <div className={styles.otpInputWrap} onPaste={handleOtpPaste}>
              {otp.map((digit, idx) => (
                <input
                  key={idx}
                  ref={(el) => (otpInputsRef.current[idx] = el)}
                  type="text"
                  inputMode="numeric"
                  maxLength={1}
                  className={`${styles.otpDigit} ${digit ? styles.otpDigitFilled : ''}`}
                  value={digit}
                  onChange={(e) => handleOtpChange(idx, e.target.value)}
                  onKeyDown={(e) => handleOtpKeyDown(idx, e)}
                />
              ))}
            </div>

            <button
              type="submit"
              className={styles.submitBtn}
              disabled={loading || otp.some((d) => d === '')}
            >
              {loading ? 'Verifying…' : <><ShieldCheck size={18} /><span>Verify &amp; Login</span></>}
            </button>

            <div className={styles.resendRow}>
              {resendTimer > 0 ? (
                <span>Resend OTP in <span className={styles.resendTimer}>{resendTimer}s</span></span>
              ) : (
                <button type="button" className={styles.resendBtn} onClick={handleSendOtp} disabled={loading}>
                  Resend OTP
                </button>
              )}
            </div>
          </form>
        )}

        <p className={styles.termsText}>
          By continuing, you agree to ProBridge's Terms of Service and Privacy Policy.
        </p>
      </div>
    </div>
  );
}
